class Solution {
    private int count = 0;

    public int pathSum(TreeNode root, int targetSum) {
        startAt(root, (long) targetSum);
        return count;
    }

    // 枚举每个节点作为起点
    private void startAt(TreeNode node, long targetSum) {
        if (node == null) return;
        fromNode(node, 0L, targetSum);
        startAt(node.left, targetSum);
        startAt(node.right, targetSum);
    }

    // 从 node 往下累加，统计和为 targetSum 的路径
    private void fromNode(TreeNode node, long sum, long targetSum) {
        if (node == null) return;
        sum += node.val;
        if (sum == targetSum) count++;
        fromNode(node.left, sum, targetSum);    // 不 return，继续往下
        fromNode(node.right, sum, targetSum);
    }
}

import java.util.*;

class Solution {
    private int count = 0;
    private Map<Long, Integer> prefix = new HashMap<>();

    public int pathSum(TreeNode root, int targetSum) {
        prefix.put(0L, 1);      // 空前缀，代表从根出发的路径
        dfs(root, 0L, (long) targetSum);
        return count;
    }

    private void dfs(TreeNode node, long cur, long targetSum) {
        if (node == null) return;

        cur += node.val;
        count += prefix.getOrDefault(cur - targetSum, 0);
        prefix.merge(cur, 1, Integer::sum);

        dfs(node.left, cur, targetSum);
        dfs(node.right, cur, targetSum);

        prefix.merge(cur, -1, Integer::sum);   // 回溯，恢复现场
    }
}

import java.util.*;

class Solution {
    public int pathSum(TreeNode root, int targetSum) {
        if (root == null) return 0;

        Map<Long, Integer> prefix = new HashMap<>();
        prefix.put(0L, 1);
        long target = (long) targetSum;
        int count = 0;

        // 栈元素：{node, parentPrefix, exiting}
        Deque<Object[]> stack = new ArrayDeque<>();
        stack.push(new Object[] { root, 0L, false });

        while (!stack.isEmpty()) {
            Object[] item = stack.pop();
            TreeNode node = (TreeNode) item[0];
            long parentPrefix = (Long) item[1];
            boolean exiting = (Boolean) item[2];

            long cur = parentPrefix + node.val;

            if (exiting) {
                prefix.merge(cur, -1, Integer::sum);   // 恢复现场
                continue;
            }

            count += prefix.getOrDefault(cur - target, 0);
            prefix.merge(cur, 1, Integer::sum);

            // 退出任务先压，保证孩子在它之前处理
            stack.push(new Object[] { node, parentPrefix, true });
            if (node.right != null) stack.push(new Object[] { node.right, cur, false });
            if (node.left != null)  stack.push(new Object[] { node.left,  cur, false });
        }
        return count;
    }
}
